import heapq
import time
from typing import Dict, Any, List, Optional, Tuple

class Peer:
    """Represents an AI peer in the cooperative mesh."""
    def __init__(self, name: str, tier: str, budget: int, latency_ms: int):
        if not isinstance(name, str) or not name: raise ValueError("Peer name must be a non-empty string.")
        if not isinstance(tier, str) or not tier: raise ValueError("Peer tier must be a non-empty string (e.g., 'TIER_A_HEAVY').")
        if not isinstance(budget, int) or budget < 0: raise ValueError("Peer budget must be a non-negative integer.")
        if not isinstance(latency_ms, int) or latency_ms < 0: raise ValueError("Peer latency must be a non-negative integer.")

        self.name: str = name
        self.tier: str = tier
        self.initial_budget: int = budget
        self.current_budget: int = budget
        self.latency_ms: int = latency_ms
        self.online: bool = True

    def __repr__(self) -> str:
        return f"Peer(name='{self.name}', tier='{self.tier}', budget={self.current_budget}/{self.initial_budget}, latency={self.latency_ms}ms, online={self.online})"

    def consume_budget(self, tokens: int) -> bool:
        """Attempts to consume tokens from the peer's current budget."""
        if tokens < 0: raise ValueError("Tokens to consume must be non-negative.")
        if self.current_budget >= tokens:
            self.current_budget -= tokens
            return True
        return False

    def reset_budget(self):
        """Resets the peer's current budget to its initial value."""
        self.current_budget = self.initial_budget

class TokenBudgetRouter:
    """Manages AI peers and selects the most suitable one for a given task."""
    def __init__(self):
        self.peers: Dict[str, Peer] = {}
        self.tier_priority: Dict[str, int] = {'S': 0, 'A': 1, 'B': 2, 'C': 3, 'D': 4} # Lower number = higher priority

    def add_peer(self, peer: Peer):
        """Adds a peer to the router."""
        if not isinstance(peer, Peer): raise TypeError("Only Peer objects can be added.")
        if peer.name in self.peers: raise ValueError(f"Peer '{peer.name}' already exists.")
        self.peers[peer.name] = peer

    def update_peer_status(self, name: str, online: Optional[bool] = None, budget_consumed: Optional[int] = None):
        """Updates a peer's online status or budget consumption."""
        if name not in self.peers: raise ValueError(f"Peer '{name}' not found.")
        peer = self.peers[name]
        if online is not None: peer.online = online
        if budget_consumed is not None: peer.consume_budget(budget_consumed)

    def select_next_peer(self, task_complexity_estimate: int = 100) -> Optional[Peer]:
        """
        Selects the best peer based on available budget, online status, tier, and latency.
        Prioritization: online & sufficient budget -> higher tier -> more remaining budget -> lower latency.
        """
        if task_complexity_estimate < 0: raise ValueError("Task complexity estimate must be non-negative.")

        eligible_peers = [p for p in self.peers.values() if p.online and p.current_budget >= task_complexity_estimate]
        if not eligible_peers: return None

        eligible_peers.sort(key=lambda p: (
            self.tier_priority.get(p.tier.split('_')[0], 99), # Extract 'S', 'A', 'B' from 'TIER_A_HEAVY'
            -p.current_budget,
            p.latency_ms
        ))
        return eligible_peers[0]

    def get_peer_status(self, name: str) -> Optional[Dict[str, Any]]:
        """Returns the status of a specific peer."""
        if name in self.peers:
            peer = self.peers[name]
            return {"name": peer.name, "tier": peer.tier, "current_budget": peer.current_budget,
                    "initial_budget": peer.initial_budget, "latency_ms": peer.latency_ms, "online": peer.online}
        return None

class Task:
    """Represents a task to be processed by the AI mesh."""
    def __init__(self, task_id: str, original_task: str, complexity: int = 100):
        if not isinstance(task_id, str) or not task_id: raise ValueError("Task ID must be a non-empty string.")
        if not isinstance(original_task, str) or not original_task: raise ValueError("Original task description must be a non-empty string.")
        if not isinstance(complexity, int) or complexity < 0: raise ValueError("Task complexity must be a non-negative integer.")

        self.task_id: str = task_id
        self.original_task: str = original_task
        self.current_state: Dict[str, Any] = {"PCT": 0, "SOLVED": "", "NEXT": original_task}
        self.assigned_peer_name: Optional[str] = None
        self.history: List[Dict[str, Any]] = []
        self.complexity: int = complexity

    def update_state(self, peer_name: str, pct: int, solved: str, next_work: str, budget_consumed: int):
        """Updates the task's progress state."""
        if not isinstance(peer_name, str) or not peer_name: raise ValueError("Peer name must be a non-empty string.")
        if not isinstance(pct, int) or not (0 <= pct <= 100): raise ValueError("Percentage complete (PCT) must be an integer between 0 and 100.")
        if not isinstance(solved, str): raise ValueError("Solved summary must be a string.")
        if not isinstance(next_work, str): raise ValueError("Next work description must be a string.")
        if not isinstance(budget_consumed, int) or budget_consumed < 0: raise ValueError("Budget consumed must be a non-negative integer.")

        self.history.append({"peer": peer_name, "timestamp": time.time(), "prev_PCT": self.current_state["PCT"],
                             "prev_SOLVED": self.current_state["SOLVED"], "prev_NEXT": self.current_state["NEXT"],
                             "new_PCT": pct, "new_SOLVED": solved, "new_NEXT": next_work, "budget_consumed": budget_consumed})
        self.current_state["PCT"] = pct
        self.current_state["SOLVED"] = solved
        self.current_state["NEXT"] = next_work
        self.assigned_peer_name = None

    def is_completed(self) -> bool:
        """Checks if the task is 100% complete."""
        return self.current_state["PCT"] >= 100

class BatonPassingQueue:
    """Manages a queue of tasks and orchestrates their assignment to peers via a router."""
    def __init__(self, router: TokenBudgetRouter):
        if not isinstance(router, TokenBudgetRouter): raise TypeError("BatonPassingQueue requires a TokenBudgetRouter instance.")
        self.router: TokenBudgetRouter = router
        self.task_queue: List[Task] = []
        self.active_tasks: Dict[str, Task] = {}

    def add_task(self, task: Task):
        """Adds a new task to the queue."""
        if not isinstance(task, Task): raise TypeError("Only Task objects can be added to the queue.")
        if task.task_id in self.active_tasks: raise ValueError(f"Task '{task.task_id}' already exists in the queue.")
        self.task_queue.append(task)
        self.active_tasks[task.task_id] = task

    def assign_next_task(self) -> Optional[Dict[str, Any]]:
        """
        Attempts to assign the next available, uncompleted task to the best eligible peer.
        Returns assignment details or None if no task can be assigned.
        """
        unassigned_tasks = [t for t in self.task_queue if not t.is_completed() and t.assigned_peer_name is None]
        if not unassigned_tasks: return None

        task_to_assign = unassigned_tasks[0] # Simple FIFO for unassigned tasks

        selected_peer = self.router.select_next_peer(task_to_assign.complexity)
        if selected_peer:
            task_to_assign.assigned_peer_name = selected_peer.name
            return {"task_id": task_to_assign.task_id, "assigned_peer": selected_peer.name,
                    "original_task": task_to_assign.original_task, "current_status": task_to_assign.current_state,
                    "estimated_complexity": task_to_assign.complexity}
        return None

    def update_task_status(self, task_id: str, peer_name: str, pct: int, solved: str, next_work: str, budget_consumed: int) -> bool:
        """
        Updates a task's status based on a peer's report and consumes the peer's budget.
        Raises ValueError if task or peer not found, or if budget consumption fails.
        """
        task = self.active_tasks.get(task_id)
        if not task: raise ValueError(f"Task '{task_id}' not found in active tasks.")
        if peer_name not in self.router.peers: raise ValueError(f"Reporting peer '{peer_name}' not found in router.")

        if task.assigned_peer_name is not None and task.assigned_peer_name != peer_name:
            print(f"Warning: Task {task_id} was assigned to '{task.assigned_peer_name}' but '{peer_name}' is reporting. Reassigning responsibility.")

        if not self.router.peers[peer_name].consume_budget(budget_consumed):
            raise ValueError(f"Peer '{peer_name}' failed to consume {budget_consumed} tokens. Current budget: {self.router.peers[peer_name].current_budget}. Task update aborted.")

        task.update_state(peer_name, pct, solved, next_work, budget_consumed)
        if task.is_completed(): print(f"Task '{task_id}' completed by '{peer_name}'!")
        return True

    def get_task_status(self, task_id: str) -> Optional[Dict[str, Any]]:
        """Returns the current status and history of a specific task."""
        task = self.active_tasks.get(task_id)
        if task:
            return {"task_id": task.task_id, "original_task": task.original_task, "current_state": task.current_state,
                    "assigned_peer": task.assigned_peer_name, "history": task.history}
        return None

    def get_all_tasks_status(self) -> List[Dict[str, Any]]:
        """Returns the status of all active tasks."""
        return [self.get_task_status(tid) for tid in self.active_tasks if self.get_task_status(tid) is not None]

```
This mechanism, you see, carefully orchestrates the flow, ensuring each 'peer' is chosen wisely based on their 'budget' and 'tier', much like assigning a complex problem to the right mind. We've built in safeguards against common errors, ensuring the 'baton' passes smoothly.

